<link rel="alternate icon" type="image/x-icon" href="../../favicon.ico?v=2"><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Create Staff Account</title><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#faf6f0;font-family:Georgia,serif;color:#3b2313}.card{width:100%;max-width:520px;background:#fff;border:1px solid #e8ddd0;border-radius:14px;padding:26px;box-shadow:0 12px 38px rgba(59,35,19,.14)}h1{margin:0 0 6px}p{color:#7a6055;margin-top:0}.field{margin:12px 0}label{display:block;font-weight:800;margin-bottom:5px}input,select{width:100%;padding:10px;border:1px solid #e8ddd0;border-radius:8px;background:#faf6f0;font:inherit}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.btn{width:100%;margin-top:14px;padding:12px;border:1px solid #a9714a;background:#a9714a;color:#fff;border-radius:8px;font:inherit;font-weight:900;cursor:pointer}.msg{display:none;margin-top:14px;padding:10px;border-radius:8px}.ok{display:block;background:#e2ecdf;color:#4f7a4a}.err{display:block;background:#f6e3dc;color:#a8492f}</style>
