</head><body><div class="card"><h1>Create Staff Account</h1><p>Use this after the applicant passes the final interview. Staff gets 8 hours/day fixed work setup.</p><div class="field"><label>Full name</label><input id="name"></div><div class="field"><label>Email</label><input id="email" type="email"></div><div class="row"><div class="field"><label>Specific role</label><input id="role" placeholder="e.g. Barista, HR Staff"></div><div class="field"><label>Department</label><select id="department"><option>Human Resources</option><option>Operations</option><option>Sales</option><option>Engineering</option><option>Cafe</option></select></div></div><div class="row"><div class="field"><label>Fixed salary</label><input id="salary" type="number" min="0" step="0.01"></div><div class="field"><label>Staff password</label><input id="password" type="text" placeholder="e.g. staff123"></div></div><button class="btn" id="createBtn">Create staff login account</button><div class="msg" id="msg"></div></div><script>const msg=document.getElementById('msg');function show(t,ok){msg.textContent=t;msg.className='msg '+(ok?'ok':'err')}document.getElementById('createBtn').onclick=async()=>{const body={name:name.value.trim(),email:email.value.trim(),role:role.value.trim(),department:department.value,fixed_salary:salary.value,password:password.value.trim(),work_hours:8};if(!body.name||!body.email||!body.role||!body.fixed_salary||!body.password){show('Please complete all fields.',false);return}try{const r=await fetch('api/employees.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();show(d.success?`Staff account created. Username: ${d.username || body.email.split('@')[0]}`:(d.message||'Failed'),!!d.success)}catch(e){show('Backend error. Check Apache/MySQL.',false)}};</script>
